def preservar_lista_antiga(apps, schema_editor):
    """A lista em texto não tem e-mail/CPF confiáveis para criar usuários;
    para não perder a informação, ela é anexada às observações da brigada."""
    Brigada = apps.get_model('accounts', 'Brigada')
    for brigada in Brigada.objects.exclude(brigadistas=''):
        lista = brigada.brigadistas.strip()
        if not lista:
            continue
        anotacao = f'Lista de brigadistas anterior (texto livre):\n{lista}'
        brigada.observacoes = f'{brigada.observacoes.rstrip()}\n\n{anotacao}' if brigada.observacoes.strip() else anotacao
        brigada.save(update_fields=['observacoes'])


